typedef unsigned int u_int;
typedef float rational_t;

class camera;
class nglLightContext;

struct nglVector
{
	float x, y, z, w;
	nglVector(float _x, float _y, float _z, float _w)
		: x(_x), y(_y), z(_z), w(_w) {}
};

struct nglMatrix
{
	float m[16];
};

class entity
{
public:
	virtual bool get_ifc_num(void *, float &);
	virtual bool set_ifc_num(void *, float);
	virtual bool get_ifc_vec(void *, void *);
	virtual bool set_ifc_vec(void *, const void *);
	virtual bool get_ifc_str(void *, void *);
	virtual bool set_ifc_str(void *, const void *);
	virtual void frame_advance(float);
	virtual void render(camera *, rational_t, int, rational_t);
};

class world_dynamics_system
{
public:
	nglLightContext *set_current_light_context(nglLightContext *);
};

extern world_dynamics_system *g_world_ptr;

class geometry_manager;
struct geometry_manager_holder
{
	void *unused;
	geometry_manager *value;
};

class geometry_manager
{
public:
	enum { XFORM_WORLD_TO_VIEW };
	char unused[64];
	nglMatrix xforms[1];
	static geometry_manager_holder *instance;
	static geometry_manager *inst() { return instance->value; }
};

template <class T> void adjustCoords(T &x, T &y);
void nglSetViewport(u_int, u_int, u_int, u_int);
void nglSetWorldToViewMatrix(const nglMatrix &);
nglLightContext *nglCreateLightContext();
void nglListAddDirLight(u_int, const nglVector &, const nglVector &);

#define NGLLIGHT_LIGHTCAT_1 0x01000000
#define RENDER_OPAQUE_PORTION 1

class FEEntityManager
{
public:
	entity *surfer_ent;
	char pad004[400];
	entity *board;
	char pad198[40];
	int cam_stopped;
	int cam_stopped_at;
	char pad1c8[84];
	camera *active_camera;
	char pad21c[36];
	int cur_state;

	enum { STATE_MAIN, STATE_SURFER1, STATE_SURFER2, STATE_TRICK };

	bool OKtoDrawBio()
	{
		return cam_stopped && cam_stopped_at == 2;
	}

	void RenderConglom(entity *);
	void DrawFront();
};

void FEEntityManager::DrawFront()
{
	// Trick Book uses same algorithm as Bio for when to draw
	if(cur_state == STATE_TRICK && OKtoDrawBio())
	{
		int x1 = 348;
		int y1 = 98;
		int x2 = 536;
		int y2 = 282;
		adjustCoords(x1, y1);
		adjustCoords(x2, y2);
		// adjust the viewport here to draw the surfer only in the window of the trick book
		// nglSetViewport operates differently in later versions of ngl
		nglSetViewport(x1, y1, x2, y2);
		nglSetWorldToViewMatrix(*(nglMatrix*)&geometry_manager::inst()->xforms[geometry_manager::XFORM_WORLD_TO_VIEW] );
		//surfer_ent[loading_surfer_ent?0:1]->render(active_camera, 1.0f, RENDER_OPAQUE_PORTION, 1.0f);

		// Create a separate nglLightContext for the trickbook. (dc 07/12/02)
		// The color and direction are the same as for the front end scene, but we need to split off
		// a second copy in order to properly use nglLightContexts.
		nglLightContext *new_lc = nglCreateLightContext();
		static nglVector trickbook_light_dir(-.718370f, -.676876f, -.160575f, 1.f);
		static nglVector trickbook_light_color(.75f, .720589f, .685294, 1.f);
		nglListAddDirLight(NGLLIGHT_LIGHTCAT_1, trickbook_light_dir, trickbook_light_color);
		nglLightContext *old_lc = g_world_ptr->set_current_light_context(new_lc);

		surfer_ent->render(active_camera, 1.0f, RENDER_OPAQUE_PORTION, 1.0f);
		RenderConglom(board);

		g_world_ptr->set_current_light_context(old_lc);
	}
}
